if (pdb.errors) throw new Error(JSON.stringify(pdb.errors));
const entry = pdb.data?.entry, citation = entry?.rcsb_primary_citation;
if (entry?.rcsb_id !== entryId || citation?.id !== 'primary' || !citation.pdbx_database_id_DOI) throw new Error('Primary citation DOI unavailable');
const doi = citation.pdbx_database_id_DOI;
const cr = await json('https://api.crossref.org/works/'+encodeURIComponent(doi));
const m = cr.message;
const normalize = s => s.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
